import Foundation

// Money Quest: a financial literacy game for Teen mode. Content lives in
// Resources/MoneyQuest/chapters.json (generated by scripts/make_money_quest.py,
// and safe for non-coders to edit). Facts that can change sit in its "facts" list.

/// Game settings in one place.
enum MoneyQuestConfig {
    /// Every player gets the same virtual monthly budget, whatever their real money.
    static let monthlyBudget: Double = 300
    static let pointsPerLevel = 20
    static let pointsPerCorrectAnswer = 5
    /// Points stop counting after this many in a day (players can keep playing for fun).
    static let dailyPointsCap = 150
    /// At most this many levels a day count towards Wisdom.
    static let wisdomLevelsPerDay = 3
    /// The virtual character's stats start here (0-200, like the real ones).
    static let startingStat = 100
}

struct QuestFact: Codable, Hashable, Identifiable, Sendable {
    let id: String
    let text: String
    let source: String
    /// Check this before any demo or launch.
    let verifyBeforeDemo: Bool
    let year: Int
}

struct QuestOption: Codable, Hashable, Sendable {
    let text: String
    let explanation: String
    /// Questions only: whether this is the right answer. Events have no right answer.
    let correct: Bool?
    /// Changes to the virtual character: stat raw values ("balance") and "money".
    let effects: [String: Int]

    var moneyChange: Int { effects["money"] ?? 0 }

    var statChanges: [(ReadinessStat, Int)] {
        ReadinessStat.allCases.compactMap { stat in effects[stat.rawValue].map { (stat, $0) } }.filter { $0.1 != 0 }
    }
}

struct QuestStep: Codable, Hashable, Identifiable, Sendable {
    enum Kind: String, Codable, Sendable { case event, question }
    let id: String
    let kind: Kind
    let prompt: String
    /// Used for "Ask Nova about this".
    let topic: String?
    let options: [QuestOption]
}

struct QuestLevel: Codable, Hashable, Identifiable, Sendable {
    let id: String
    let title: String
    let persona: String
    let steps: [QuestStep]
    let learned: [String]

    var questionCount: Int { steps.filter { $0.kind == .question }.count }
}

struct QuestChapter: Codable, Hashable, Identifiable, Sendable {
    let id: Int
    let title: String
    let symbol: String
    let summary: String
    /// Only one level so far: needs more content before launch.
    let needsMoreContent: Bool
    let levels: [QuestLevel]
}

struct MoneyQuestContent: Codable, Sendable {
    let version: Int
    let facts: [QuestFact]
    let chapters: [QuestChapter]

    static let empty = MoneyQuestContent(version: 0, facts: [], chapters: [])

    /// Loaded once from the app bundle.
    static let shared: MoneyQuestContent = {
        guard let url = Bundle.main.url(forResource: "chapters", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let content = try? JSONDecoder().decode(MoneyQuestContent.self, from: data) else { return .empty }
        return content
    }()

    /// Replaces {{fact:id}} with the fact's text.
    func resolve(_ text: String) -> String {
        guard text.contains("{{fact:") else { return text }
        var result = text
        for fact in facts { result = result.replacingOccurrences(of: "{{fact:\(fact.id)}}", with: fact.text) }
        return result
    }

    func chapter(containing levelID: String) -> QuestChapter? {
        chapters.first { $0.levels.contains { $0.id == levelID } }
    }
}

/// Saved game progress. Badges are for finishing chapters, never for speed.
struct GameProgress: Codable, Hashable, Sendable {
    var completedLevels: [String] = []
    var bestCorrect: [String: Int] = [:]
    var totalPoints = 0
    var pointsByDay: [String: Int] = [:]
    var wisdomLevelsByDay: [String: Int] = [:]
    var badges: [Int] = []

    init() {}

    nonisolated init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        completedLevels = try c.decodeIfPresent([String].self, forKey: .completedLevels) ?? []
        bestCorrect = try c.decodeIfPresent([String: Int].self, forKey: .bestCorrect) ?? [:]
        totalPoints = try c.decodeIfPresent(Int.self, forKey: .totalPoints) ?? 0
        pointsByDay = try c.decodeIfPresent([String: Int].self, forKey: .pointsByDay) ?? [:]
        wisdomLevelsByDay = try c.decodeIfPresent([String: Int].self, forKey: .wisdomLevelsByDay) ?? [:]
        badges = try c.decodeIfPresent([Int].self, forKey: .badges) ?? []
    }

    func pointsToday(now: Date = .now) -> Int { pointsByDay[MoneyQuestRules.dayKey(now)] ?? 0 }
    func isComplete(_ levelID: String) -> Bool { completedLevels.contains(levelID) }
}

struct LevelReward: Hashable, Sendable {
    let pointsEarned: Int
    /// True when the daily cap stopped some points.
    let hitDailyCap: Bool
    let countsForWisdom: Bool
    let newBadgeChapter: Int?
}

/// Pure game rules.
enum MoneyQuestRules {
    static func dayKey(_ date: Date, calendar: Calendar = .current) -> String {
        let c = calendar.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d", c.year ?? 0, c.month ?? 0, c.day ?? 0)
    }

    /// Applies a finished level: points (capped per day), Wisdom (first completion,
    /// at most 3 levels a day) and a badge when a chapter is finished.
    static func complete(levelID: String, chapter: QuestChapter, correct: Int, progress: GameProgress, now: Date = .now) -> (GameProgress, LevelReward) {
        var p = progress
        let day = dayKey(now)
        let earned = MoneyQuestConfig.pointsPerLevel + correct * MoneyQuestConfig.pointsPerCorrectAnswer
        let room = max(0, MoneyQuestConfig.dailyPointsCap - (p.pointsByDay[day] ?? 0))
        let granted = min(earned, room)
        p.pointsByDay[day, default: 0] += granted
        p.totalPoints += granted

        let firstTime = !p.completedLevels.contains(levelID)
        let wisdomToday = p.wisdomLevelsByDay[day] ?? 0
        let countsForWisdom = firstTime && wisdomToday < MoneyQuestConfig.wisdomLevelsPerDay
        if countsForWisdom { p.wisdomLevelsByDay[day] = wisdomToday + 1 }
        if firstTime { p.completedLevels.append(levelID) }
        p.bestCorrect[levelID] = max(p.bestCorrect[levelID] ?? 0, correct)

        var badge: Int?
        if !p.badges.contains(chapter.id), chapter.levels.allSatisfy({ p.completedLevels.contains($0.id) }) {
            p.badges.append(chapter.id)
            badge = chapter.id
        }
        return (p, LevelReward(pointsEarned: granted, hitDailyCap: granted < earned, countsForWisdom: countsForWisdom, newBadgeChapter: badge))
    }
}
